import {
  GET_PROFILE_REQUEST,
  GET_PROFILE_SUCCESS,
  GET_PROFILE_FAILURE,
} from "./type"

// POST_PAYMENT_INFORMATION
export const profileRequest = (data) => ({
  type: GET_PROFILE_REQUEST,
  data
})

export const profileSuccess = data => ({
  type: GET_PROFILE_SUCCESS,
  data
})

export const profileFailure = data => ({
  type: GET_PROFILE_FAILURE,
  data
})
