import {
  GET_PROFILE_REQUEST,
  GET_PROFILE_SUCCESS,
  GET_PROFILE_FAILURE,
} from "./type"

const initialState = {
  profileData: false,
  error: false,
  requesting: false,
}

export default (state = initialState, action) => {
  switch (action.type) {
    case GET_PROFILE_REQUEST:
      return {
        ...state,
        requesting: true
      }

    case GET_PROFILE_SUCCESS:
      return {
        ...state,
        requesting: false,
        profileData: action.data
      }
    case GET_PROFILE_FAILURE:
      return {
        ...state,
        requesting: false,
        error: action.data
      }

    default:
      return state
  }
}
