import React, {useEffect} from 'react'
import HomeLayout from '../../layout/HomeLayout'
import { Images } from '../../theme/Images'
import UInput from '../../components/UInput'
import Button from '../../components/Button'
import ProfileReviewsCard from '../../components/ProfileReviewsCard'

import './style.scss';
import { history } from '../../reduxStore/store'

import {
    profileRequest,
    profileFailure,
} from './redux/action'

// Routing
import { connect } from 'react-redux';


const Profile = (props) => {
    const {
        userProfile
        // error,
        // requesting,
        // profileFailure,
    } = props;

    // useEffect(() => {
    //     profileRequest()
    // }, [])

    return (
        <HomeLayout contentClassName='overflow-hidden'>
            <div className="profile-section-wrapper">
                <div className="navigate-head flex-align-center">
                    <img src={Images.backArrow} onClick={() => history.goBack()} alt="" />
                    <p>{userProfile.name}</p>
                </div>
                <div className="profile-wrapper">
                    <div className="profile-details-wrapper">
                        <div className="profile-details">
                            <div className="profile-info">
                                <div className="avatar">
                                    <img src={userProfile.photo} alt="" />
                                </div>
                                <p>{userProfile.name}</p>
                            </div>
                            <div className="profile-fields-wrapper">
                                <UInput
                                    placeholder='Name'
                                    value={userProfile.name}
                                />
                                <UInput
                                    placeholder='Email'
                                    value={userProfile.email}
                                />
                                <UInput
                                    placeholder='Phone Number'
                                    value={userProfile.phone_number}
                                />
                                <UInput
                                    placeholder='Main Address'
                                    value={userProfile.address}
                                />
                                <div className="button-wrapper">
                                    <Button
                                        title='Remove'
                                        className='transparent-red-btn full-width'
                                    />
                                </div>
                            </div>
                        </div>
                    </div>
                    <div className="profile-reviews">
                        <h3>Reviews</h3>
                        <div className="profile-reviews-card-wrapper">
                            {userProfile && userProfile?.reviews.map((data, index) => (
                                <ProfileReviewsCard data={data}/>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </HomeLayout>
    )
}

const mapStateToProps = (state) => ({
    userProfile: state.profiles.profileData,
    error: state.profiles.error,
    requesting: state.profiles.requesting,
});

const mapDispatchToProps = (dispatch) => ({
    profileRequest: (data) => dispatch(profileRequest(data)),
    profileFailure: (data) => dispatch(profileFailure(data)),
});

export default connect(mapStateToProps, mapDispatchToProps)(Profile);
